#!/usr/bin/env python3
# ---------------------------------------------------------------------------
# pocket-voxel patcher: Viridian City sleeping-man block + catch-tutorial wiring
# (patcher 1 of 2 — map-script + save-backed object toggles; TS-only, no cargo)
#
# Ports data/scripts/story.lua M.VIRIDIAN_CITY from ~/gen1recomp:
#   * both old-man talk scripts (SLEEPY grumble+shove, OLD_MAN coffee/hurry ask
#     leading into the WEEDLE catch demo)
#   * the north-corridor block at (19,9), gated on EVENT_GOT_POKEDEX
#   * the Pokédex old-man swap re-derive on entry (#234)
# plus the infra it needs: save.objectToggles persistence for ShowObject/
# HideObject (so Oak's-lab swap survives the trip to Viridian) and the
# old_man_demo opcode (hands off to the demo battle staged in patcher 2).
#
# Idempotent: each hunk is skipped if already applied. Aborts loudly if a base
# anchor is missing or ambiguous (wrong tree / already diverged).
# Run from ~/pocket-voxel:  python3 apply_viridian_oldman_1.py
# ---------------------------------------------------------------------------
import base64, sys, os

HUNKS = [{'path': 'voxelmon/game/world/overworld.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/world/overworld.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/world/overworld.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/world/script.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/world/script.ts', 'old': 'ICAgIG91dGRvb3I6IHNhdmUubGFzdE91dGRvb3IgPyB7IC4uLnNhdmUubGFzdE91dGRvb3IgfSA6IHVuZGVmaW5lZCwKICB9Owp9Cgpjb25zdCBWRVJCUzogUmVjb3JkPHN0cmluZywgVmVyYj4gPSB7CiAgc2hvd190ZXh0LAogIGFzaywKICBqdW1wLAo=', 'new': ''}, {'path': 'voxelmon/game/world/script.ts', 'old': 'ICByaXZhbF9iYXR0bGUsCiAgd2Fsa19ucGMsCiAgZW5nYWdlX3RyYWluZXIsCiAgc2V0X2hlYWxfcG9pbnQsCiAgcHVzaF9zY3JlZW46IG5vb3Bfb2JqZWN0LAogIHBsYXlfc291bmQ6IG5vb3BfYXVkaW8sCiAgcGxheV9tdXNpYzogbm9vcF9hdWRpbywKICBzdG9wX211c2ljOiBub29wX2F1ZGlvLAo=', 'new': 'ICByaXZhbF9iYXR0bGUsCiAgd2Fsa19ucGMsCiAgZW5nYWdlX3RyYWluZXIsCiAgc2V0X2hlYWxfcG9pbnQsCiAgb2xkX21hbl9kZW1vLAogIHB1c2hfc2NyZWVuOiBub29wX29iamVjdCwKICBwbGF5X3NvdW5kOiBub29wX2F1ZGlvLAogIHBsYXlfbXVzaWM6IG5vb3BfYXVkaW8sCiAgc3RvcF9tdXNpYzogbm9vcF9hdWRpbywK'}, {'path': 'voxelmon/game/world/mapscripts.ts', 'old': '', 'new': ''}]

def main():
    root = os.getcwd()
    if not os.path.isdir(os.path.join(root, "voxelmon")):
        sys.exit("! run this from the pocket-voxel repo root (no ./voxelmon here)")
    changed = 0; skipped = 0
    # group by file so we read/write each once
    by_file = {}
    for h in HUNKS:
        by_file.setdefault(h["path"], []).append(h)
    for path, hs in by_file.items():
        fp = os.path.join(root, path)
        if not os.path.isfile(fp):
            sys.exit(f"! missing file: {path}")
        text = open(fp, encoding="utf-8").read()
        orig = text
        for h in hs:
            old = base64.b64decode(h["old"]).decode()
            new = base64.b64decode(h["new"]).decode()
            if new in text:
                skipped += 1
                continue
            n = text.count(old)
            if n == 0:
                sys.exit(f"! anchor not found in {path}\n  (already modified, or not the expected base tree)")
            if n > 1:
                sys.exit(f"! anchor is ambiguous in {path} ({n} matches) — aborting")
            text = text.replace(old, new, 1)
            changed += 1
        if text != orig:
            open(fp, "w", encoding="utf-8").write(text)
            print(f"  patched {path}")
    print(f"done: {changed} hunk(s) applied, {skipped} already present")
    if changed == 0 and skipped:
        print("(nothing to do — patcher already applied)")

if __name__ == "__main__":
    main()
